 $q=$db->prepare("SELECT c.*,lc.name category_name,lc.icon category_icon,lc.slug category_slug FROM learning_courses c LEFT JOIN learning_categories lc ON lc.id=c.category_id WHERE c.slug=? AND c.enabled=1 LIMIT 1");$q->execute([$slug]);$course=$q->fetch(PDO::FETCH_ASSOC)?:null;if(!$course)throw new RuntimeException('not-found');
 $hasCh=(int)$db->query("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='learning_lessons' AND column_name='chapter_id'")->fetchColumn()>0;
 if($hasCh&&(int)$db->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='learning_chapters'")->fetchColumn()>0){try{$q=$db->prepare("SELECT l.id,l.title,l.slug,l.sort_order,ch.title chapter_title FROM learning_lessons l JOIN learning_chapters ch ON ch.id=l.chapter_id WHERE ch.course_id=? AND l.enabled=1 ORDER BY ch.sort_order,ch.id,l.sort_order,l.id");$q->execute([(int)$course['id']]);$lessons=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}}
 if(!$lessons&&(int)$db->query("SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='learning_lessons' AND column_name='course_id'")->fetchColumn()>0){$q=$db->prepare("SELECT l.id,l.title,l.slug,l.sort_order,NULL chapter_title FROM learning_lessons l WHERE l.course_id=? AND l.enabled=1 ORDER BY l.sort_order,l.id");$q->execute([(int)$course['id']]);$lessons=$q->fetchAll(PDO::FETCH_ASSOC);}
}catch(Throwable){}
